/**
 * Theme v5 schema and sparse inheritance builder (`docs/theme.md`).
 *
 * A theme is four orthogonal TypeScript layers derived from one `base` theme via `defineTheme()`:
 * 1. `tokens`   — the core CSS variables compiled into `theme.json`, including `font-sans` / `font-mono`
 * 2. `metrics`  — pointer/touch dimensions, icon sizes, strokes, and per-role font weight/tracking
 * 3. `surfaces` — 11 semantic surface layers + per-appearance elevation scales (no finish-fields allowlist)
 * 4. `feedback` & `motion` — unified hover/press/focus/disabled feedback primitives and motion timings/presets
 * 5. `controls` — 13 sparse control recipes with numerical/degenerate defaults (no theme-ID branches)
 *
 * L1 `ThemeParadigm` (`paradigm.ts`) is an authoring shorthand. `defineTheme` expands it into these
 * L2 fields and does not store `paradigm` on the resolved `ThemeSpec`.
 */

import { expandParadigm, type ParadigmPatch, type ThemeParadigm } from "./paradigm";

/** Platform glass/acrylic material requests (`null` = pure CSS/layer paint). */
export type FinishMaterial = "glass" | "acrylic";

/** Both appearances. */
export type Mode = "light" | "dark";

/** Appearance pair. */
export interface Appearance<T> {
  readonly light: T;
  readonly dark: T;
}

/** Input-tier pair: desktop pointer vs touch screen. */
export interface Tiered<T> {
  readonly pointer: T;
  readonly touch: T;
}

export type TieredOrFlat<T> = T | Tiered<T>;
export type ModeOrFlat<T> = T | Appearance<T>;

/** The 21 per-appearance color keys in `theme.json` (`brand` is optional in source, defaulting to `var(--primary)`). */
export type CoreColorKey =
  | "background"
  | "card"
  | "popover"
  | "muted"
  | "surface"
  | "foreground"
  | "muted-foreground"
  | "faint"
  | "primary"
  | "primary-foreground"
  | "secondary"
  | "accent"
  | "brand"
  | "border"
  | "line"
  | "input"
  | "ring"
  | "info"
  | "success"
  | "warning"
  | "destructive";

/** The 3 appearance-invariant color keys in `theme.json`. */
export type FixedColorKey = "scrim" | "media" | "on-media";

/** Standard status tone keys. */
export type ToneColorKey = "info" | "success" | "warning" | "destructive";

/** Any color key declared in `theme.json`. */
export type AnyColorKey = CoreColorKey | FixedColorKey;

/** Palette written by each theme per appearance (`brand` defaults to `primary`). */
export interface CorePalette {
  readonly background: string;
  readonly card: string;
  readonly popover: string;
  readonly muted: string;
  readonly surface: string;
  readonly foreground: string;
  readonly "muted-foreground": string;
  readonly faint: string;
  readonly primary: string;
  readonly "primary-foreground": string;
  readonly secondary: string;
  readonly accent: string;
  /** Brand ink for links, carets, active markers; defaults to `var(--primary)` when omitted. */
  readonly brand?: string;
  readonly border: string;
  readonly line: string;
  readonly input: string;
  readonly ring: string;
  readonly info: string;
  readonly success: string;
  readonly warning: string;
  readonly destructive: string;
}

/** Reference to a color inside theme recipes. */
export type ColorExpr =
  | AnyColorKey
  | (string & {})
  | { readonly color: AnyColorKey; readonly alpha: number }
  | { readonly tint: "brand" | ToneColorKey; readonly alpha?: number };

/** Reference to a surface or color face in a control slot. */
export type FaceExpr = ColorExpr | { readonly surface: SurfaceRole };

/** Elevation shadow scale per appearance. */
export interface ElevationScale {
  readonly sm: string | null;
  readonly md: string | null;
  readonly lg: string | null;
  readonly xl: string | null;
  readonly inset: string | null;
  readonly edgeSurface?: string | null;
  readonly edgeAccent?: string | null;
}

export type ShadowPart = keyof ElevationScale;
export type ShadowExpr = ShadowPart | readonly ShadowPart[] | (string & {}) | null;

/** `UIBlurEffectStyle` materials. Names match NSH `BackdropMaterial`. */
export type IosBackdropMaterial = "ultraThin" | "thin" | "regular" | "thick" | "chrome";

/** `NSVisualEffectMaterial`. Names match NSH `MacOsBackdropMaterial`. */
export type MacOsBackdropMaterial =
  | "titlebar"
  | "selection"
  | "menu"
  | "popover"
  | "sidebar"
  | "headerView"
  | "sheet"
  | "windowBackground"
  | "hudWindow"
  | "fullScreenUI"
  | "toolTip"
  | "contentBackground"
  | "underWindowBackground"
  | "underPageBackground";

/** `NSVisualEffectBlendingMode`. Names match NSH `MacOsBackdropBlending`. */
export type MacOsBackdropBlending = "withinWindow" | "behindWindow";

/** `NSVisualEffectState`. Names match NSH `MacOsBackdropState`. */
export type MacOsBackdropState = "followsWindowActiveState" | "active" | "inactive";

/**
 * A macOS backdrop: a material name, or a material with blending and window state.
 * Names match NSH `MacOsBackdrop`.
 */
export type MacOsBackdropSpec =
  | MacOsBackdropMaterial
  | {
      readonly material?: MacOsBackdropMaterial;
      readonly blending?: MacOsBackdropBlending;
      readonly state?: MacOsBackdropState;
    };

/** Parameterized optical backdrop/specular material configuration for a surface layer. */
export interface MaterialSpec {
  readonly kind: "glass" | "acrylic" | "blur";
  readonly blur?: number;
  readonly saturate?: number;
  readonly minOpacity?: number;
  readonly specular?: ColorExpr | null;
  /** Liquid Glass style. Falls back to the kind's recipe when omitted. */
  readonly glass?: "regular" | "clear";
  /** iOS system material of the layer's blur (`ios={{ backdropMaterial }}`). */
  readonly ios?: IosBackdropMaterial;
  /** macOS visual-effect backdrop (`macos={{ backdrop }}`). */
  readonly macos?: MacOsBackdropSpec;
}

/** Material request on a surface layer: built-in platform preset name or parameterized spec. */
export type SurfaceMaterial = FinishMaterial | MaterialSpec;

/** Built-in GPU WGSL surface texture/optics shader presets matching major platform aesthetics. */
export type SurfaceEffectKind = "liquid-glass" | "acrylic-noise" | "specular-rim" | "paper-grain";

/** Optional GPU surface shader effect with automatic fallback when shaders are unavailable. */
export interface SurfaceEffectSpec {
  readonly kind: SurfaceEffectKind;
  /** Effect strength in (0, 1]; defaults per kind. */
  readonly intensity?: number;
  /** Optional custom WGSL `fn shade(uv: vec2f) -> vec4f` source overriding the built-in shader. */
  readonly wgsl?: string;
}

/** The 11 pure structural surfaces (`hover`, `pressed`, `disabled` live in `feedback`; `knob` in controls). */
export type SurfaceRole =
  | "card"
  | "raised"
  | "inset"
  | "channel"
  | "plate"
  | "overlay"
  | "modal"
  | "inverse"
  | "glass"
  | "accent"
  | "fill";

export interface SurfaceLayer {
  readonly background?: ColorExpr | null;
  readonly foreground?: ColorExpr;
  readonly gradient?: string | null;
  readonly border?: ColorExpr | null;
  readonly borderTop?: ColorExpr | null;
  readonly borderBottom?: ColorExpr | null;
  readonly shadow?: ShadowExpr;
  readonly backdropFilter?: string | null;
  readonly material?: SurfaceMaterial | null;
  readonly effect?: SurfaceEffectSpec | null;
  readonly elevation?: number | null;
}

export interface SurfaceSpec extends SurfaceLayer {
  readonly light?: Partial<SurfaceLayer>;
  readonly dark?: Partial<SurfaceLayer>;
}

export interface Steps {
  readonly sm: number;
  readonly md: number;
  readonly lg: number;
}

export type TypeRole = "caption" | "detail" | "body" | "label" | "title" | "headline" | "display";

export interface TypographyMetric {
  readonly fontWeight: number;
  readonly letterSpacing: number;
}

export type EasingName =
  | "out-cubic"
  | "in-cubic"
  | "in-out-cubic"
  | "standard"
  | "emphasized-decelerate"
  | "emphasized-accelerate"
  | "decelerate"
  | "accelerate"
  | "point-to-point";

export interface TimingSpec {
  readonly duration: number;
  readonly easing: EasingName;
}

export interface TokensSpec {
  /**
   * Font families emitted into `theme.json` `cssVars.theme`.
   * Omitted families compile to `font-sans: system-ui` and `font-mono: monospace`.
   */
  readonly font?: {
    readonly sans?: string;
    readonly mono?: string;
  };
  readonly radius: {
    readonly control: number;
    readonly container: number;
    readonly modal: number;
    readonly curve: "continuous" | "circular";
  };
  readonly fixed: {
    readonly scrim: string;
    readonly media: string;
    readonly "on-media": string;
  };
  readonly light: CorePalette;
  readonly dark: CorePalette;
  /** Default translucent alpha used by `tints.*` (`color-mix(in srgb, token N%, transparent)`). */
  readonly tintAlpha: Appearance<number>;
  /** Optional solid/custom tint overrides per appearance/tone (e.g. Material/WinUI tonal surfaces). */
  readonly tints?: Partial<Appearance<Partial<Record<"brand" | ToneColorKey, string>>>>;
  /** Optional 5-color chart ramp override; defaults to `[brand, info, success, warning, destructive]`. */
  readonly chart?: Appearance<readonly [ColorExpr, ColorExpr, ColorExpr, ColorExpr, ColorExpr]>;
}

export interface MetricsSpec {
  readonly height: Tiered<Steps>;
  readonly icon: Tiered<Steps>;
  readonly density: Tiered<{ readonly pad: number; readonly gap: number }>;
  readonly control: Tiered<{ readonly padding: number; readonly gap: number }>;
  readonly item: Tiered<{ readonly inset: number; readonly pad: number }>;
  readonly hit: Tiered<number>;
  readonly stroke: { readonly hairline: number; readonly control: number };
  readonly typography: Record<TypeRole, TypographyMetric>;
}

export interface FeedbackSpec {
  readonly hover: {
    /** State-layer ink wash opacity (> 0 draws overlay instead of swapping fill). */
    readonly overlay: number;
    /** Generic hover background fill (`hovered()`). */
    readonly fill: ModeOrFlat<ColorExpr>;
    /** Raised control hover surface overrides. */
    readonly surface: SurfaceSpec;
  };
  readonly press: {
    /** Transform scale when pressed (`1` disables press sink). */
    readonly scale: number;
    /** Vertical press travel in points (`0` by default; extensible). */
    readonly translateY: number;
    /** Pressed state-layer ink wash opacity. */
    readonly overlay: number;
    /** Secondary/raised control pressed surface. */
    readonly surface: SurfaceSpec;
    /** Filled accent button/control press behavior. */
    readonly accent: {
      readonly opacity: number;
      readonly background?: ModeOrFlat<ColorExpr> | null;
      readonly foreground?: ModeOrFlat<ColorExpr> | null;
    };
  };
  readonly focus: {
    readonly style: "halo" | "outline" | "double";
    readonly width: number;
    readonly offset: number;
    /** Inner separator line for `"double"` focus rings. */
    readonly innerColor?: ModeOrFlat<ColorExpr>;
  };
  readonly disabled: {
    readonly contentOpacity: number;
    /** When true, disabled surfaces swap to `disabled.surface` rather than dimming resting surface. */
    readonly replaceFace: boolean;
    readonly surface: SurfaceSpec;
  };
  readonly passive: {
    readonly restOpacity: number;
    readonly pressedOpacity: number;
  };
}

/** Physics spring parameters for native NSH motion (`stiffness`, `damping`, optional `mass`). */
export interface MotionSpringSpec {
  readonly stiffness: number;
  readonly damping: number;
  readonly mass?: number;
}

/** Named physics springs a preset can point at (`motion.springs`). */
export type SpringRole = "snappy" | "smooth" | "bouncy";

/**
 * One spring per role. A missing role falls back to `motion.spring`.
 * The object itself is not atomic, so a patch can replace a single role.
 */
export interface MotionSpringsSpec {
  readonly snappy?: MotionSpringSpec;
  readonly smooth?: MotionSpringSpec;
  readonly bouncy?: MotionSpringSpec;
}

/** Built-in transition style used when switching themes at runtime (`selectTheme`). */
export type ThemeSwitchKind = "none" | "fade" | "dissolve" | "radial-wipe";

export interface MotionSpec {
  readonly state: TimingSpec;
  readonly fast: TimingSpec;
  readonly default: TimingSpec;
  readonly slow: TimingSpec;
  readonly spring?: MotionSpringSpec;
  /** Named springs. Each role replaces as a whole (`MotionSpringSpec` is atomic). */
  readonly springs?: MotionSpringsSpec;
  readonly presets: {
    readonly popoverEnter: {
      readonly fromScale: number;
      readonly fromY: number;
      readonly timing: "fast" | "default";
      /** `true` uses `motion.spring`; a role uses `motion.springs`. */
      readonly spring?: boolean | SpringRole;
    };
    readonly dialogEnter: {
      readonly fromScale: number;
      readonly fromY: number;
      readonly timing: "fast" | "default" | "slow";
      /** `true` uses `motion.spring`; a role uses `motion.springs`. */
      readonly spring?: boolean | SpringRole;
    };
    readonly indicatorGlide: {
      readonly timing: "fast" | "default";
      /** `true` uses `motion.spring`; a role uses `motion.springs`. */
      readonly spring?: boolean | SpringRole;
    };
    /** Panel reveal (`Accordion` / `Collapsible`). Omitted themes keep the host default. */
    readonly reveal?: {
      readonly spring?: boolean | SpringRole;
    };
    /** Press feedback. Omitted themes keep the cubic-bezier state transition. */
    readonly press?: {
      readonly spring?: boolean | SpringRole;
    };
    readonly themeSwitch: {
      readonly kind: ThemeSwitchKind;
      readonly duration: number;
    };
  };
}

export type SlotCorner = number | "control" | "container" | "full";
export type SlotSize = number | readonly [number, number] | "same";

export interface ControlsSpec {
  readonly button: {
    readonly corner: {
      readonly sm: TieredOrFlat<SlotCorner>;
      readonly md: TieredOrFlat<SlotCorner>;
      readonly lg: TieredOrFlat<SlotCorner>;
    };
    readonly selected: { readonly face: FaceExpr; readonly ink: ColorExpr };
    readonly secondary: { readonly face: FaceExpr; readonly edge: FaceExpr | "none" };
    readonly outline: { readonly edge: FaceExpr };
    readonly destructive: { readonly edge: ColorExpr | "none" };
    readonly shade: SurfaceRole | "none";
  };
  readonly badge: { readonly corner: SlotCorner };
  readonly field: {
    readonly ground: ModeOrFlat<ColorExpr>;
    readonly shade: SurfaceRole | "none";
    readonly edge: {
      readonly sides: boolean;
      readonly color: ColorExpr;
      readonly bottom: ColorExpr;
    };
    readonly focus: {
      readonly line: boolean;
      readonly width: number;
      readonly color: "brand" | "ring";
    };
  };
  readonly choice: {
    readonly size: TieredOrFlat<number>;
    readonly box: TieredOrFlat<number>;
    readonly corner: TieredOrFlat<SlotCorner>;
    readonly face: ModeOrFlat<ColorExpr | "none">;
    readonly shade: SurfaceRole | "none";
    readonly edge: {
      readonly width: number;
      readonly color: ModeOrFlat<ColorExpr | "none">;
      readonly disabled: ModeOrFlat<ColorExpr | "none">;
    };
    readonly checked: { readonly face: FaceExpr | "none" };
    readonly radioChecked: { readonly face: FaceExpr | "none" };
    readonly mark: TieredOrFlat<number>;
  };
  readonly switch: {
    readonly track: TieredOrFlat<readonly [number, number]>;
    readonly trackOffFace: ModeOrFlat<ColorExpr>;
    readonly small: {
      readonly track: TieredOrFlat<readonly [number, number]>;
      readonly knob: TieredOrFlat<SlotSize>;
    };
    readonly edge: {
      readonly off: TieredOrFlat<number>;
      readonly on: TieredOrFlat<number>;
      readonly color: ColorExpr | "none";
    };
    readonly knob: {
      readonly size: TieredOrFlat<SlotSize>;
      /** Retained numeric degenerate slot: Material grows knob when checked; others use `"same"`. */
      readonly on: TieredOrFlat<SlotSize>;
      readonly pressed: TieredOrFlat<SlotSize>;
      readonly background: ModeOrFlat<ColorExpr>;
      readonly gradient?: ModeOrFlat<string | null>;
      readonly border: ModeOrFlat<ColorExpr>;
      readonly shadow: ShadowExpr;
      readonly checkedBackground?: ModeOrFlat<ColorExpr>;
      readonly checkedBorder?: ModeOrFlat<ColorExpr>;
      readonly checkedGradient?: ModeOrFlat<string | null>;
    };
  };
  readonly slider: {
    readonly rail: TieredOrFlat<number>;
    readonly band: TieredOrFlat<number>;
    readonly face: ModeOrFlat<ColorExpr>;
    readonly shade: SurfaceRole | "none";
    readonly edge: { readonly color: ColorExpr | "none"; readonly width: number };
    readonly knob: {
      readonly size: TieredOrFlat<SlotSize>;
      readonly pressed: TieredOrFlat<SlotSize>;
      readonly background: ModeOrFlat<ColorExpr>;
      readonly gradient?: ModeOrFlat<string | null>;
      readonly border: ModeOrFlat<ColorExpr | "none">;
      readonly shadow: ShadowExpr;
    };
    /** Retained numeric degenerate slot: WinUI ring inner dot diameter (`0` elsewhere). */
    readonly mark: TieredOrFlat<number>;
  };
  readonly progress: {
    readonly height: number;
    readonly face: ModeOrFlat<ColorExpr>;
    readonly shade: SurfaceRole | "none";
    readonly edge: { readonly color: ColorExpr | "none"; readonly width: number };
  };
  readonly spinner: {
    readonly trackOpacity: number;
  };
  readonly popup: {
    readonly corner: SlotCorner;
  };
  readonly list: {
    readonly item: {
      readonly highlight: ColorExpr;
      readonly edge: ColorExpr | "none";
    };
  };
  readonly tabs: {
    readonly track: {
      readonly face: ModeOrFlat<ColorExpr | "none">;
      readonly edge: ColorExpr | "none";
      readonly corner: SlotCorner;
    };
  };
  readonly menubar: { readonly bar: "card" | "none" };
  readonly well: { readonly edge: ColorExpr | "none" };
}

export interface ContrastWaiver {
  readonly fg: string;
  readonly bg: string;
  readonly source: string;
}

export interface ThemeMeta {
  readonly overview?: string;
  readonly elevationNote?: string;
  readonly dos?: readonly string[];
  readonly donts?: readonly string[];
  readonly contrastWaivers?: readonly ContrastWaiver[];
  readonly scaleCitations?: Readonly<Record<string, string>>;
}

export interface ThemeSpec {
  readonly id: string;
  readonly label: string;
  readonly tokens: TokensSpec;
  readonly metrics: MetricsSpec;
  readonly elevation: Appearance<ElevationScale>;
  readonly surfaces: Record<SurfaceRole, SurfaceSpec>;
  readonly feedback: FeedbackSpec;
  readonly motion: MotionSpec;
  readonly controls: ControlsSpec;
  readonly meta?: ThemeMeta;
}

/** Deep partial helper preserving atomic leaf unions/tuples while allowing sparse tiered/nested patches. */
export type DeepPartial<T> = T extends readonly unknown[]
  ? T
  : T extends { readonly pointer: infer P; readonly touch: infer Q }
    ? { readonly pointer?: DeepPartial<P>; readonly touch?: DeepPartial<Q> }
    : T extends
          | { readonly color: AnyColorKey; readonly alpha: number }
          | { readonly tint: "brand" | ToneColorKey }
          | { readonly surface: SurfaceRole }
          | { readonly duration: number; readonly easing: string }
          | MotionSpringSpec
          | MaterialSpec
          | SurfaceEffectSpec
      ? T
      : T extends object
        ? { readonly [K in keyof T]?: DeepPartial<T[K]> }
        : T;

export interface ThemePatch extends Omit<DeepPartial<ThemeSpec>, "id" | "label" | "meta"> {
  readonly id: string;
  readonly label: string;
  readonly extends: ThemeSpec;
  /**
   * L1 axes. Expanded after `extends` and before this patch's own L2 fields, which win.
   * Stripped from the resolved `ThemeSpec`.
   */
  readonly paradigm?: ThemeParadigm;
  readonly meta?: ThemeMeta;
}

/** NSH `theme.json` payload consumed by `setTheme` and Tailwind. */
export interface NshThemeFile {
  readonly name: string;
  readonly cssVars: {
    readonly theme: Record<string, string>;
    readonly light: Record<string, string>;
    readonly dark: Record<string, string>;
  };
}

/** One runtime-switchable theme (`selectTheme`). */
export interface AppTheme {
  readonly id: string;
  readonly label: string;
  /** Compiled `theme.json` for NSH `setTheme` (shared radii and fonts, plus 21 colors per appearance). */
  readonly theme: NshThemeFile;
  /** Resolved semantic spec (`tokens` + `metrics` + `surfaces` + `feedback` + `motion` + `controls`). */
  readonly spec: ThemeSpec;
}

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/** Material and surface-effect specs replace as a whole so a patch cannot leave a half-merged kind. */
const isMaterialOrEffect = (v: Record<string, unknown>): boolean =>
  "kind" in v &&
  typeof v.kind === "string" &&
  (v.kind === "glass" ||
    v.kind === "acrylic" ||
    v.kind === "blur" ||
    v.kind === "liquid-glass" ||
    v.kind === "acrylic-noise" ||
    v.kind === "specular-rim" ||
    v.kind === "paper-grain");

const isAtomicObject = (v: Record<string, unknown>): boolean =>
  isMaterialOrEffect(v) ||
  ("color" in v &&
    typeof v.color === "string" &&
    "alpha" in v &&
    Object.keys(v).every((k) => k === "color" || k === "alpha")) ||
  ("tint" in v && typeof v.tint === "string") ||
  ("surface" in v && typeof v.surface === "string" && Object.keys(v).length === 1) ||
  ("duration" in v && typeof v.duration === "number" && "easing" in v) ||
  ("stiffness" in v && typeof v.stiffness === "number" && "damping" in v);

function deepMerge<T>(base: T, patch: unknown): T {
  if (patch === undefined) return base;
  if (patch === null || typeof patch !== "object" || Array.isArray(patch)) return patch as T;
  if (!isPlainObject(base) || !isPlainObject(patch)) return patch as T;
  if (isAtomicObject(patch) || isAtomicObject(base)) return patch as T;
  // `knob.{background,border,checkedBackground,checkedBorder,gradient,checkedGradient}` and `choice.*`:
  // if either side is non-record and we handled primitives above, both are `{light, dark}` or plain records.
  const out: Record<string, unknown> = { ...base };
  for (const [k, v] of Object.entries(patch)) {
    if (v === undefined) continue;
    out[k] = k in base ? deepMerge(base[k], v) : v;
  }
  return out as T;
}

const APPEARANCE_KEYS: readonly (keyof CorePalette)[] = [
  "background",
  "card",
  "popover",
  "muted",
  "surface",
  "foreground",
  "muted-foreground",
  "faint",
  "primary",
  "primary-foreground",
  "secondary",
  "accent",
  "brand",
  "border",
  "line",
  "input",
  "ring",
  "info",
  "success",
  "warning",
  "destructive",
];

function compilePalette(palette: CorePalette): Record<string, string> {
  const out: Record<string, string> = {};
  for (const key of APPEARANCE_KEYS) {
    if (key === "brand") {
      out.brand = palette.brand ?? "var(--primary)";
    } else {
      out[key] = palette[key];
    }
  }
  return out;
}

/** Compile a `ThemeSpec`'s `tokens` into the minimal NSH `theme.json` structure. */
export function compileNshTheme(spec: ThemeSpec): NshThemeFile {
  const { font, radius, fixed, light, dark } = spec.tokens;
  const themeVars: Record<string, string> = {
    "font-sans": font?.sans ?? "system-ui",
    "font-mono": font?.mono ?? "monospace",
    radius: `${radius.control}px`,
    "radius-md": `${radius.control}px`,
    "radius-lg": `${radius.container}px`,
    "radius-xl": `${radius.modal}px`,
    scrim: fixed.scrim,
    media: fixed.media,
    "on-media": fixed["on-media"],
  };
  return {
    name: spec.label,
    cssVars: {
      theme: themeVars,
      light: compilePalette(light),
      dark: compilePalette(dark),
    },
  };
}

export const SHARED_TYPE_SCALE: Record<
  TypeRole,
  { readonly fontSize: Tiered<number>; readonly lineHeight: Tiered<number> }
> = {
  caption: { fontSize: { pointer: 11, touch: 12 }, lineHeight: { pointer: 16, touch: 16 } },
  detail: { fontSize: { pointer: 12, touch: 13 }, lineHeight: { pointer: 16, touch: 20 } },
  body: { fontSize: { pointer: 13, touch: 15 }, lineHeight: { pointer: 20, touch: 20 } },
  label: { fontSize: { pointer: 14, touch: 15 }, lineHeight: { pointer: 20, touch: 20 } },
  title: { fontSize: { pointer: 16, touch: 16 }, lineHeight: { pointer: 24, touch: 24 } },
  headline: { fontSize: { pointer: 20, touch: 22 }, lineHeight: { pointer: 28, touch: 28 } },
  display: { fontSize: { pointer: 26, touch: 28 }, lineHeight: { pointer: 32, touch: 36 } },
};

export const EASING_BEZIERS: Record<EasingName, readonly [number, number, number, number]> = {
  "out-cubic": [0.333333, 1, 0.666667, 1],
  "in-cubic": [0.333333, 0, 0.666667, 0],
  "in-out-cubic": [0.65, 0, 0.35, 1],
  standard: [0.2, 0, 0, 1],
  "emphasized-decelerate": [0.05, 0.7, 0.1, 1],
  "emphasized-accelerate": [0.3, 0, 0.8, 0.15],
  decelerate: [0, 0, 0, 1],
  accelerate: [1, 0, 1, 1],
  "point-to-point": [0.55, 0.55, 0, 1],
};

/** Merge a paradigm's sparse L2 fields onto a base spec. Identity and `meta` stay put. */
function withParadigm(base: ThemeSpec, patch: ParadigmPatch): ThemeSpec {
  return {
    ...base,
    tokens: mergeTokens(base.tokens, patch.tokens),
    metrics: deepMerge(base.metrics, patch.metrics),
    elevation: deepMerge(base.elevation, patch.elevation),
    surfaces: deepMerge(base.surfaces, patch.surfaces),
    feedback: deepMerge(base.feedback, patch.feedback),
    motion: deepMerge(base.motion, patch.motion),
    controls: deepMerge(base.controls, patch.controls),
  };
}

function mergeTokens(base: TokensSpec, patch: ThemePatch["tokens"]): TokensSpec {
  const merged = deepMerge(base, patch);
  if (!patch?.light && !patch?.dark) return merged;
  return {
    ...merged,
    light: patch.light ? { ...merged.light, brand: patch.light.brand } : merged.light,
    dark: patch.dark ? { ...merged.dark, brand: patch.dark.brand } : merged.dark,
    tints: patch.tints,
    chart: patch.chart as TokensSpec["chart"],
  };
}

/**
 * Create a complete `ThemeSpec` and runtime `AppTheme` from either a full `ThemeSpec` or a sparse
 * patch extending another theme. When `paradigm` is set, the merge order is the extended theme,
 * then `expandParadigm`, then the patch's own L2 fields. Omitting `paradigm` keeps the previous merge.
 */
export function defineTheme(input: ThemeSpec | ThemePatch): AppTheme {
  const base =
    "extends" in input
      ? input.paradigm
        ? withParadigm(input.extends, expandParadigm(input.paradigm))
        : input.extends
      : undefined;
  const spec: ThemeSpec =
    base !== undefined && "extends" in input
      ? {
          id: input.id,
          label: input.label,
          tokens: mergeTokens(base.tokens, input.tokens),
          metrics: deepMerge(base.metrics, input.metrics),
          elevation: deepMerge(base.elevation, input.elevation),
          surfaces: deepMerge(base.surfaces, input.surfaces),
          feedback: deepMerge(base.feedback, input.feedback),
          motion: deepMerge(base.motion, input.motion),
          controls: deepMerge(base.controls, input.controls),
          meta: input.meta,
        }
      : (input as ThemeSpec);
  return {
    id: spec.id,
    label: spec.label,
    theme: compileNshTheme(spec),
    spec,
  };
}

// The platform materials a finish can ask for, and what each guarantees where the platform has
// none of them. From the NSH design guides; yours to change.
import type { BackdropMaterial, MacOsBackdrop, WindowsBackdropMaterial } from "nsh";

import type {
  ColorExpr,
  FinishMaterial,
  MacOsBackdropSpec,
  MaterialSpec,
  SurfaceMaterial,
} from "./schema";

export type { FinishMaterial };

/**
 * What one material asks of NSH, and what it guarantees a platform that has none of it.
 *
 * NSH has no SVG filters: a material is either the platform's own (Liquid Glass, the Windows 11
 * backdrop blur) or a blur of what is behind the view (`backdropFilter`) — never a refraction, a
 * noise or a luminosity blend, which the platform draws for us or not at all.
 */
export interface MaterialRecipe {
  /**
   * Liquid Glass on iOS 26 and macOS 26 and later, as the style key it rides in (`glassEffect`,
   * with the layer's own colour as `glassTintColor`). NSH draws the finish's `backdropFilter` on
   * every other platform, so a recipe states a glass or a platform backdrop, never both.
   */
  glassEffect?: "regular" | "clear";
  /** NSH's platform props: `platformMaterial()` spreads them on the view that draws the finish. */
  props: {
    /** The system material of the finish's `backdropFilter` blur (`ios={{ backdropMaterial }}`). */
    ios?: { backdropMaterial: BackdropMaterial };
    /** The system blur of what is behind the window (`windows={{ backdrop }}`), Windows 11 (22000) and later. */
    windows?: { backdrop: { material: WindowsBackdropMaterial } };
    /** AppKit visual-effect backdrop (`macos={{ backdrop }}`). */
    macos?: { readonly backdrop: MacOsBackdrop };
  };
  /** What every platform that draws no material of its own draws instead. */
  fallback: {
    /** The blur the layer wears, in points: `backdropFilter` is the only blur NSH has. */
    blur: number;
    /**
     * The least opaque the layer's own fill may be, so that a platform which draws no blur (Linux,
     * GPUI) shows nothing through the layer's fill. A theme states its fills at or above it.
     */
    minOpacity: number;
  };
}

/**
 * The recipes, by material: what `Finish.material` names.
 *
 * `glass` is Liquid Glass: the system glass on iOS 26 and macOS 26 and later, with the layer's
 * colour as its tint, and a 30pt blur elsewhere — the layer's fill is at least 0.72 opaque, so what
 * is behind it never comes through unfiltered. `acrylic` is Windows 11's Acrylic: the system blur of
 * what is behind the window, over a fill that states WinUI's tint and luminosity (0.85 light, 0.96
 * dark, in `themes/winui/`), falling back to a 30pt blur elsewhere. Both numbers are the guide's;
 * they are checked against platform screenshots, not derived.
 */
export const materials: Record<FinishMaterial, MaterialRecipe> = {
  glass: {
    glassEffect: "regular",
    props: { ios: { backdropMaterial: "regular" } },
    fallback: { blur: 30, minOpacity: 0.72 },
  },
  acrylic: {
    props: { windows: { backdrop: { material: "blur" } } },
    fallback: { blur: 30, minOpacity: 0.85 },
  },
};

/**
 * A material after its preset or spec has been resolved: platform props, the blur every other
 * platform draws, and the opacity floor the layer's own fill must meet.
 */
export interface ResolvedMaterial {
  /** Liquid Glass style, only when the recipe is the system's glass. */
  readonly glassEffect?: "regular" | "clear";
  /** Platform props `surface()` spreads onto the view (`ios` / `windows` / `macos`). */
  readonly props: MaterialRecipe["props"];
  /** Backdrop blur in points. */
  readonly blur: number;
  /** Least opacity of the layer's own fill. */
  readonly minOpacity: number;
  /** Backdrop saturation multiplier (`1.8` is `saturate(180%)`), when the spec states one. */
  readonly saturate?: number;
  /** Specular hairline color, when the spec states one. */
  readonly specular?: ColorExpr | null;
}

const BLUR_FALLBACK = { blur: 16, minOpacity: 0.68 } as const;

/** Fill AppKit's backdrop defaults. An explicit blending or state wins. */
function macosBackdrop(spec: MacOsBackdropSpec): { readonly backdrop: MacOsBackdrop } {
  if (typeof spec === "string") {
    return {
      backdrop: {
        material: spec,
        blending: "withinWindow",
        state: "followsWindowActiveState",
      },
    };
  }
  return {
    backdrop: {
      ...(spec.material !== undefined ? { material: spec.material } : {}),
      blending: spec.blending ?? "withinWindow",
      state: spec.state ?? "followsWindowActiveState",
    },
  };
}

function withOptics(spec: MaterialSpec, resolved: ResolvedMaterial): ResolvedMaterial {
  return {
    ...resolved,
    ...(spec.saturate !== undefined ? { saturate: spec.saturate } : {}),
    ...(spec.specular !== undefined ? { specular: spec.specular } : {}),
  };
}

/** Resolve a preset name or a `MaterialSpec` into one recipe a surface can paint. */
export function resolveMaterial(material: SurfaceMaterial): ResolvedMaterial {
  if (typeof material === "string") {
    const recipe = materials[material];
    return {
      ...(recipe.glassEffect !== undefined ? { glassEffect: recipe.glassEffect } : {}),
      props: recipe.props,
      blur: recipe.fallback.blur,
      minOpacity: recipe.fallback.minOpacity,
    };
  }
  if (material.kind === "blur") {
    return withOptics(material, {
      props: {
        ...(material.ios ? { ios: { backdropMaterial: material.ios } } : {}),
        ...(material.macos ? { macos: macosBackdrop(material.macos) } : {}),
      },
      blur: material.blur ?? BLUR_FALLBACK.blur,
      minOpacity: material.minOpacity ?? BLUR_FALLBACK.minOpacity,
    });
  }
  const recipe = materials[material.kind];
  const glassEffect = material.glass ?? recipe.glassEffect;
  return withOptics(material, {
    ...(glassEffect !== undefined ? { glassEffect } : {}),
    props: {
      ...(material.ios
        ? { ios: { backdropMaterial: material.ios } }
        : recipe.props.ios
          ? { ios: recipe.props.ios }
          : {}),
      ...(recipe.props.windows ? { windows: recipe.props.windows } : {}),
      ...(material.macos ? { macos: macosBackdrop(material.macos) } : {}),
    },
    blur: material.blur ?? recipe.fallback.blur,
    minOpacity: material.minOpacity ?? recipe.fallback.minOpacity,
  });
}

/**
 * Built-in WGSL surface and theme-switch shaders.
 *
 * Pure TypeScript and shader source: this file does not import `nsh`, so the CLI, Node and Bun
 * tests can read it. NSH supplies `nsh`, `uniforms`, `sample_content`, `sample_backdrop`,
 * `sample_from` and `sample_to` when it compiles a source.
 */
import type { SurfaceEffectKind, SurfaceEffectSpec, ThemeSwitchKind } from "./schema";

const HASH = /* wgsl */ `
fn hash(p: vec2f) -> f32 {
  let q = bitcast<vec2u>(vec2i(floor(p)));
  var h = (q.x * 1597334677u) ^ (q.y * 3812015801u);
  h = h * 1664525u + 1013904223u;
  h = (h ^ (h >> 16u)) * 2246822519u;
  h = h ^ (h >> 13u);
  return f32(h >> 8u) / 16777216.0;
}`;

const NOISE = /* wgsl */ `${HASH}
fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2f(1.0, 0.0)), u.x),
    mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), u.x),
    u.y
  );
}`;

/**
 * Built-in surface shaders, keyed by `SurfaceEffectKind`.
 * Every source declares `struct Uniforms { intensity: f32 }` and `fn shade(uv: vec2f) -> vec4f`.
 */
export const SURFACE_SHADERS: Record<
  SurfaceEffectKind,
  { readonly source: string; readonly defaultIntensity: number; readonly maxSampleOffset: number }
> = {
  "liquid-glass": {
    defaultIntensity: 0.35,
    // Bend 4.5pt + chroma 0.7pt stays inside this budget. Do not grow either without raising it.
    maxSampleOffset: 6,
    source: /* wgsl */ `
struct Uniforms { intensity: f32 }

fn sd_round_box(p: vec2f, half: vec2f, rad: f32) -> f32 {
  let q = abs(p) - half + vec2f(rad);
  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - rad;
}

fn box_normal(p: vec2f, half: vec2f, rad: f32) -> vec2f {
  let q = abs(p) - half + vec2f(rad);
  let outside = max(q, vec2f(0.0));
  let len = length(outside);
  let corner = q.x > 0.0 && q.y > 0.0 && len > 0.0001;
  let along_x = q.x >= q.y;
  let sx = select(-1.0, 1.0, p.x > 0.0);
  let sy = select(-1.0, 1.0, p.y > 0.0);
  let axis = select(vec2f(0.0, sy), vec2f(sx, 0.0), along_x);
  let curved = vec2f((outside.x / max(len, 0.0001)) * sx, (outside.y / max(len, 0.0001)) * sy);
  return select(axis, curved, corner);
}

fn shade(uv: vec2f) -> vec4f {
  let size = max(nsh.size, vec2f(1.0));
  let p = (uv - vec2f(0.5)) * size;
  let rad = min(min(size.x, size.y) * 0.28, 18.0);
  let sd = sd_round_box(p, size * 0.5, rad);
  let inside = smoothstep(0.5, -0.5, sd);
  let nrm = box_normal(p, size * 0.5, rad);
  let rim = smoothstep(16.0, 0.0, -sd) * inside;

  // Transparent optical rim overlay: leave the center clear so native NSGlassEffectView / CSS
  // backdropFilter and surface fill show through, while refracting and highlighting the bezel.
  let bend = nrm * rim * uniforms.intensity * 4.5;
  let chroma = nrm * rim * uniforms.intensity * 0.7;
  let sample_mid = sample_backdrop(uv + bend / size);
  let split_r = sample_backdrop(uv + (bend + chroma) / size);
  let split_b = sample_backdrop(uv + (bend - chroma) / size);
  let lens = vec3f(split_r.r, sample_mid.g, split_b.b);
  let luma = dot(lens, vec3f(0.2126, 0.7152, 0.0722));
  let vivid = clamp(mix(vec3f(luma), lens, 1.0 + uniforms.intensity * 0.45), vec3f(0.0), vec3f(1.0));
  let refract_a = rim * rim * uniforms.intensity * 0.55 * sample_mid.a;

  let top = clamp(-nrm.y, 0.0, 1.0) * rim;
  let sheen_a = clamp(top * uniforms.intensity * 0.65, 0.0, 1.0);
  let edge = smoothstep(1.5, 0.0, abs(sd)) * inside;
  let edge_a = clamp(edge * uniforms.intensity * 0.45, 0.0, 1.0);
  let bottom = clamp(nrm.y, 0.0, 1.0) * rim;
  let shadow_a = clamp(bottom * uniforms.intensity * 0.22, 0.0, 1.0);

  let light_a = clamp(sheen_a + edge_a, 0.0, 1.0);
  let base_rgb = mix(vivid, vec3f(0.0), shadow_a);
  let base_a = clamp(refract_a + shadow_a, 0.0, 1.0);
  let total_a = clamp(base_a + light_a * (1.0 - base_a), 0.0, 1.0);
  let rgb = select(vec3f(0.0), mix(base_rgb * base_a, vec3f(1.0), light_a) / total_a, total_a > 0.001);
  return vec4f(clamp(rgb, vec3f(0.0), vec3f(1.0)), total_a * inside);
}`,
  },
  "acrylic-noise": {
    defaultIntensity: 0.04,
    // Pure grain + 1px specular highlight overlay; backdrop blur & tint live on the host layer.
    maxSampleOffset: 0,
    source: /* wgsl */ `${HASH}
struct Uniforms { intensity: f32 }
fn shade(uv: vec2f) -> vec4f {
  let size = max(nsh.size, vec2f(1.0));
  let grain = hash(uv * nsh.size * max(nsh.scale, 1.0)) - 0.5;
  let px = 1.0 / max(nsh.scale, 1.0);
  let top = smoothstep(px, 0.0, uv.y * size.y);

  let grain_rgb = select(vec3f(0.0), vec3f(1.0), grain > 0.0);
  let grain_a = clamp(abs(grain) * uniforms.intensity * 1.6, 0.0, 1.0);
  let top_a = clamp(top * 0.22, 0.0, 1.0);
  let total_a = clamp(grain_a + top_a * (1.0 - grain_a), 0.0, 1.0);
  let rgb = select(vec3f(0.0), mix(grain_rgb * grain_a, vec3f(1.0), top_a) / total_a, total_a > 0.001);
  return vec4f(clamp(rgb, vec3f(0.0), vec3f(1.0)), total_a);
}`,
  },
  "specular-rim": {
    defaultIntensity: 0.4,
    maxSampleOffset: 0,
    source: /* wgsl */ `
struct Uniforms { intensity: f32 }
fn shade(uv: vec2f) -> vec4f {
  let top = smoothstep(0.22, 0.0, uv.y);
  let edge = min(min(uv.x, 1.0 - uv.x), min(uv.y, 1.0 - uv.y));
  let rim = smoothstep(0.06, 0.0, edge);
  let bottom = smoothstep(0.76, 1.0, uv.y);

  let light_a = clamp((top * 0.32 + rim * 0.28) * uniforms.intensity, 0.0, 1.0);
  let dark_a = clamp(bottom * uniforms.intensity * 0.22, 0.0, 1.0);
  let total_a = clamp(dark_a + light_a * (1.0 - dark_a), 0.0, 1.0);
  let rgb = select(vec3f(0.0), vec3f(light_a / total_a), total_a > 0.001);
  return vec4f(clamp(rgb, vec3f(0.0), vec3f(1.0)), total_a);
}`,
  },
  "paper-grain": {
    defaultIntensity: 0.03,
    maxSampleOffset: 0,
    source: /* wgsl */ `${NOISE}
struct Uniforms { intensity: f32 }
fn shade(uv: vec2f) -> vec4f {
  let p = uv * nsh.size * max(nsh.scale, 1.0);
  let low = noise(p / 42.0);
  let high = noise(p / 3.5);
  let grain = (low - 0.5) * 0.65 + (high - 0.5) * 0.35;
  let warm_rgb = vec3f(0.88, 0.82, 0.72);
  let warm_a = clamp(uniforms.intensity * 0.65, 0.0, 1.0);
  let grain_rgb = select(vec3f(0.25, 0.22, 0.18), vec3f(1.0), grain > 0.0);
  let grain_a = clamp(abs(grain) * uniforms.intensity * 1.4, 0.0, 1.0);
  let total_a = clamp(warm_a + grain_a * (1.0 - warm_a), 0.0, 1.0);
  let rgb = select(vec3f(0.0), (warm_rgb * warm_a * (1.0 - grain_a) + grain_rgb * grain_a) / total_a, total_a > 0.001);
  return vec4f(clamp(rgb, vec3f(0.0), vec3f(1.0)), total_a);
}`,
  },
};

/**
 * Theme-switch shaders for the kinds that are not a plain fade.
 * Every source defines `fn shade(uv: vec2f) -> vec4f` and reads `nsh.progress`, `sample_from` and `sample_to`.
 */
export const TRANSITION_SHADERS: Record<
  Exclude<ThemeSwitchKind, "none" | "fade">,
  { readonly source: string }
> = {
  dissolve: {
    source: /* wgsl */ `${HASH}
fn shade(uv: vec2f) -> vec4f {
  let n = hash(uv * nsh.size * max(nsh.scale, 1.0));
  let t = 1.0 - smoothstep(nsh.progress - 0.06, nsh.progress + 0.06, n);
  return mix(sample_from(uv), sample_to(uv), t);
}`,
  },
  "radial-wipe": {
    source: /* wgsl */ `
fn shade(uv: vec2f) -> vec4f {
  let aspect = nsh.size.x / max(nsh.size.y, 1.0);
  let p = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  let d = length(p);
  let reach = nsh.progress * 1.15;
  let t = 1.0 - smoothstep(reach, reach + 0.12, d);
  return mix(sample_from(uv), sample_to(uv), t);
}`,
  },
};

/** A surface effect ready to hand to `ShaderEffect`. */
export interface ResolvedSurfaceEffect {
  /** WGSL source (`fn shade`). */
  readonly source: string;
  /** Uniforms the source's `struct Uniforms` reads. */
  readonly uniforms: { readonly intensity: number };
  /** How far, in points, samples may reach outside the view. */
  readonly maxSampleOffset: number;
}

/** Resolve a surface effect spec to shader source and uniforms, or `null` when unset. */
export function resolveSurfaceEffect(
  spec: SurfaceEffectSpec | null | undefined,
): ResolvedSurfaceEffect | null {
  if (spec == null) return null;
  const built = SURFACE_SHADERS[spec.kind];
  return {
    source: spec.wgsl ?? built.source,
    uniforms: { intensity: spec.intensity ?? built.defaultIntensity },
    maxSampleOffset: built.maxSampleOffset,
  };
}

/** WGSL for a theme-switch kind, or `null` for `"none"` and `"fade"`. */
export function resolveTransitionShader(kind: ThemeSwitchKind): string | null {
  switch (kind) {
    case "none":
    case "fade":
      return null;
    case "dissolve":
    case "radial-wipe":
      return TRANSITION_SHADERS[kind].source;
    default: {
      const exhaustive: never = kind;
      return exhaustive;
    }
  }
}

/**
 * L1 theme paradigm: six semantic axes expanded into a sparse L2 patch.
 *
 * Pure TypeScript. This module does not import `nsh`, so build scripts and unit tests can load it.
 * Durations, hit targets, and material opacity stay inside `scripts/theme/invariants.ts`.
 */
import type { EasingName, ElevationScale, SlotCorner, ThemePatch, TimingSpec } from "./schema";

/** How far a surface lifts off the page. */
export type ParadigmDepth = "flat" | "hairline" | "soft-shadow" | "glass" | "acrylic";

/** Corner family for controls and containers. */
export type ParadigmShape = "sharp" | "rounded" | "soft" | "pill";

/** Edge weight and contrast. */
export type ParadigmStroke = "crisp" | "hairline" | "translucent";

/** Motion tempo, including the theme-switch transition. */
export type ParadigmMotion = "snappy" | "fluid" | "springy" | "instant";

/** How a control answers hover, press, and focus. */
export type ParadigmFeedback = "tint" | "underline" | "lift" | "ring";

/** Pointer and touch spacing, on the 4px grid. */
export type ParadigmDensity = "compact" | "balanced" | "airy";

/** Optional semantic axes. An omitted axis leaves the base theme's L2 fields alone. */
export interface ThemeParadigm {
  /** Surface lift: flat fill, hairline, soft shadow, glass, or acrylic. */
  readonly depth?: ParadigmDepth;
  /** Corner family. `"pill"` capsules controls and keeps container radii. */
  readonly shape?: ParadigmShape;
  /** Stroke width, and for `"translucent"` a quieter edge. */
  readonly stroke?: ParadigmStroke;
  /** Timing scale and `motion.presets.themeSwitch`. */
  readonly motion?: ParadigmMotion;
  /** Hover, press, and focus treatment. */
  readonly feedback?: ParadigmFeedback;
  /** Pointer and touch metrics. Touch stays at least as large as pointer. */
  readonly density?: ParadigmDensity;
}

/**
 * Sparse L2 fields a paradigm expands into.
 * A `ThemePatch` also carries `id`, `label`, and `extends`; those stay on the `defineTheme` call.
 */
export type ParadigmPatch = Omit<ThemePatch, "id" | "label" | "extends" | "paradigm" | "meta">;

type Plain = Record<string, unknown>;

const isPlain = (value: unknown): value is Plain =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/** Color, tint, material, effect, timing, and spring objects replace as a whole. */
const isAtomic = (value: Plain): boolean =>
  ("kind" in value && typeof value.kind === "string") ||
  ("color" in value && "alpha" in value) ||
  ("tint" in value && typeof value.tint === "string") ||
  ("duration" in value && "easing" in value) ||
  ("stiffness" in value && "damping" in value);

function merge<T>(base: T, patch: unknown): T {
  if (patch === undefined) return base;
  if (patch === null || typeof patch !== "object" || Array.isArray(patch)) return patch as T;
  if (!isPlain(base) || !isPlain(patch)) return patch as T;
  if (isAtomic(patch) || isAtomic(base)) return patch as T;
  const out: Plain = { ...base };
  for (const [key, value] of Object.entries(patch)) {
    if (value === undefined) continue;
    out[key] = key in base ? merge(base[key], value) : value;
  }
  return out as T;
}

const mergePatch = (base: ParadigmPatch, patch: ParadigmPatch): ParadigmPatch => merge(base, patch);

const timing = (duration: number, easing: EasingName): TimingSpec => ({ duration, easing });

const veil = (alpha: number) => ({ color: "border" as const, alpha });

const flatElevation = (): ElevationScale => ({
  sm: null,
  md: null,
  lg: null,
  xl: null,
  inset: null,
  edgeSurface: null,
  edgeAccent: null,
});

const hairlineElevation = (ring: string): ElevationScale => ({
  sm: ring,
  md: null,
  lg: null,
  xl: null,
  inset: null,
  edgeSurface: ring,
  edgeAccent: null,
});

const softLight: ElevationScale = {
  sm: "0 1px 2px oklch(0 0 0 / 0.06)",
  md: "0 4px 12px oklch(0 0 0 / 0.08)",
  lg: "0 12px 28px oklch(0 0 0 / 0.12)",
  xl: "0 20px 48px oklch(0 0 0 / 0.16)",
  inset: "inset 0 1px 2px oklch(0 0 0 / 0.05)",
  edgeSurface: "0 0 0 1px oklch(0 0 0 / 0.06)",
  edgeAccent: null,
};

const softDark: ElevationScale = {
  sm: "0 1px 2px oklch(0 0 0 / 0.28)",
  md: "0 4px 12px oklch(0 0 0 / 0.36)",
  lg: "0 12px 28px oklch(0 0 0 / 0.46)",
  xl: "0 20px 48px oklch(0 0 0 / 0.56)",
  inset: "inset 0 1px 2px oklch(0 0 0 / 0.35)",
  edgeSurface: "0 0 0 1px oklch(1 0 0 / 0.08)",
  edgeAccent: null,
};

function depthPatch(depth: ParadigmDepth): ParadigmPatch {
  if (depth === "flat") {
    const clear = {
      shadow: null,
      gradient: null,
      backdropFilter: null,
      material: null,
      effect: null,
      border: "border" as const,
    };
    return {
      elevation: { light: flatElevation(), dark: flatElevation() },
      surfaces: {
        card: { ...clear, background: "card" },
        plate: {
          ...clear,
          light: { background: "card", border: "border", shadow: null },
          dark: { background: "card", border: "border", shadow: null },
        },
        raised: {
          ...clear,
          background: "surface",
          light: {
            background: "surface",
            border: "border",
            borderTop: "border",
            borderBottom: "border",
            shadow: null,
          },
          dark: {
            background: "surface",
            border: "border",
            borderTop: "border",
            borderBottom: "border",
            shadow: null,
          },
        },
        overlay: { ...clear, background: "popover" },
        modal: { ...clear, background: "card" },
      },
    };
  }
  if (depth === "hairline") {
    return {
      elevation: {
        light: hairlineElevation("0 0 0 1px oklch(0 0 0 / 0.12)"),
        dark: hairlineElevation("0 0 0 1px oklch(1 0 0 / 0.16)"),
      },
      surfaces: {
        card: {
          border: "border",
          shadow: "sm",
          material: null,
          effect: null,
          backdropFilter: null,
        },
        raised: {
          border: "border",
          shadow: "sm",
          material: null,
          effect: null,
          backdropFilter: null,
        },
        overlay: {
          border: "border",
          shadow: "sm",
          material: null,
          effect: null,
          backdropFilter: null,
        },
        plate: {
          border: "border",
          shadow: "sm",
          material: null,
          effect: null,
          backdropFilter: null,
        },
        modal: {
          border: "border",
          shadow: "sm",
          material: null,
          effect: null,
          backdropFilter: null,
        },
      },
    };
  }
  if (depth === "soft-shadow") {
    return {
      elevation: { light: softLight, dark: softDark },
      surfaces: {
        card: { shadow: "md", material: null, effect: null, backdropFilter: null },
        overlay: { shadow: "lg", material: null, effect: null, backdropFilter: null },
        modal: { shadow: "xl", material: null, effect: null, backdropFilter: null },
      },
    };
  }
  // Preset floors: glass 0.72, acrylic 0.85 (`materials.ts`). Fills sit strictly above them.
  const glassAlpha = depth === "acrylic" ? 0.9 : 0.78;
  const material = depth === "acrylic" ? "acrylic" : "glass";
  const effect =
    depth === "acrylic"
      ? { kind: "acrylic-noise" as const, intensity: 0.035 }
      : { kind: "liquid-glass" as const, intensity: 0.35 };
  const overlayEffect =
    depth === "acrylic"
      ? { kind: "acrylic-noise" as const, intensity: 0.035 }
      : { kind: "specular-rim" as const, intensity: 0.4 };
  const fill = {
    light: { background: { color: "popover" as const, alpha: glassAlpha } },
    dark: { background: { color: "popover" as const, alpha: glassAlpha } },
  };
  return {
    surfaces: {
      glass: {
        material,
        effect,
        backdropFilter: "blur(30px)",
        ...fill,
      },
      overlay: {
        material,
        effect: overlayEffect,
        backdropFilter: "blur(30px)",
        ...fill,
      },
    },
  };
}

function radii(
  control: number,
  container: number,
  modal: number,
  curve: "continuous" | "circular",
) {
  return { control, container, modal, curve };
}

function corners(corner: SlotCorner): NonNullable<ParadigmPatch["controls"]> {
  return {
    button: { corner: { sm: corner, md: corner, lg: corner } },
    badge: { corner },
    tabs: { track: { corner } },
  };
}

function shapePatch(shape: ParadigmShape): ParadigmPatch {
  if (shape === "sharp") {
    return {
      tokens: { radius: radii(4, 4, 6, "circular") },
      controls: {
        ...corners(2),
        choice: { corner: { pointer: 2, touch: 4 } },
        popup: { corner: 4 },
      },
    };
  }
  if (shape === "rounded") {
    return {
      tokens: { radius: radii(8, 12, 14, "continuous") },
      controls: {
        ...corners("control"),
        choice: { corner: { pointer: 6, touch: 8 } },
        popup: { corner: "container" },
      },
    };
  }
  if (shape === "soft") {
    return {
      tokens: { radius: radii(12, 16, 20, "continuous") },
      controls: {
        ...corners("control"),
        choice: { corner: { pointer: 8, touch: 12 } },
        popup: { corner: "container" },
      },
    };
  }
  // Capsule the interactive controls. Container and modal radii stay with the base.
  return {
    controls: {
      ...corners("full"),
      badge: { corner: "full" },
      tabs: { track: { corner: "full" } },
    },
  };
}

function strokePatch(stroke: ParadigmStroke): ParadigmPatch {
  if (stroke === "hairline") {
    return {
      metrics: { stroke: { hairline: 0.5, control: 1 } },
      controls: { choice: { edge: { width: 0.5 } } },
    };
  }
  if (stroke === "translucent") {
    const edge = veil(0.45);
    return {
      metrics: { stroke: { hairline: 1, control: 1 } },
      surfaces: {
        card: { border: edge },
        raised: { border: edge },
        overlay: { border: veil(0.4) },
        modal: { border: veil(0.4) },
      },
      controls: {
        choice: { edge: { width: 1, color: veil(0.5) } },
        field: { edge: { color: edge, bottom: veil(0.7) } },
      },
    };
  }
  return {
    metrics: { stroke: { hairline: 1, control: 1 } },
    controls: { choice: { edge: { width: 1 } } },
  };
}

function motionPatch(motion: ParadigmMotion): ParadigmPatch {
  if (motion === "instant") {
    // `state` / `fast` / `default` / `slow` cannot be 0. Only the theme switch can.
    return {
      motion: {
        state: timing(40, "out-cubic"),
        fast: timing(60, "out-cubic"),
        default: timing(100, "out-cubic"),
        slow: timing(150, "out-cubic"),
        presets: { themeSwitch: { kind: "none", duration: 0 } },
      },
    };
  }
  if (motion === "snappy") {
    return {
      motion: {
        state: timing(80, "out-cubic"),
        fast: timing(100, "out-cubic"),
        default: timing(160, "out-cubic"),
        slow: timing(260, "out-cubic"),
        presets: { themeSwitch: { kind: "fade", duration: 140 } },
      },
    };
  }
  if (motion === "fluid") {
    return {
      motion: {
        state: timing(120, "standard"),
        fast: timing(140, "standard"),
        default: timing(220, "standard"),
        slow: timing(360, "standard"),
        presets: { themeSwitch: { kind: "dissolve", duration: 280 } },
      },
    };
  }
  // zeta = 34 / (2 * sqrt(420 * 1)) ≈ 0.83, inside [0.55, 1.5].
  return {
    motion: {
      state: timing(80, "point-to-point"),
      fast: timing(160, "point-to-point"),
      default: timing(240, "point-to-point"),
      slow: timing(380, "point-to-point"),
      spring: { stiffness: 420, damping: 34, mass: 1 },
      presets: {
        popoverEnter: { spring: true },
        dialogEnter: { spring: true },
        indicatorGlide: { timing: "fast", spring: true },
        themeSwitch: { kind: "radial-wipe", duration: 320 },
      },
    },
  };
}

function feedbackPatch(feedback: ParadigmFeedback): ParadigmPatch {
  if (feedback === "tint") {
    return {
      feedback: {
        hover: { overlay: 0.06, fill: { color: "foreground", alpha: 0.08 } },
        press: { scale: 0.98, overlay: 0.1, accent: { opacity: 0.84 } },
      },
    };
  }
  if (feedback === "underline") {
    return {
      feedback: { focus: { style: "outline", width: 2, offset: 0 } },
      controls: {
        field: {
          edge: { sides: false, bottom: "brand" },
          focus: { line: true, width: 2, color: "brand" },
        },
      },
    };
  }
  if (feedback === "lift") {
    return {
      feedback: {
        hover: { overlay: 0.08, fill: { color: "foreground", alpha: 0.06 } },
        press: { scale: 0.94, translateY: -1 },
      },
    };
  }
  return {
    feedback: { focus: { style: "outline", width: 2, offset: 2 } },
    controls: { field: { focus: { line: false, width: 2, color: "ring" } } },
  };
}

interface Steps {
  readonly sm: number;
  readonly md: number;
  readonly lg: number;
